import { gsap } from 'gsap';
import { ScrollSmoother } from 'gsap/ScrollSmoother.js';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';

export default class Lines {
  constructor(element) {
    //register des plugins mis dans le gsap
    gsap.registerPlugin(ScrollSmoother, ScrollTrigger);
    this.element = element;

    this.options = {
      offset: -250,
    };

    this.path = this.element.querySelector('path');
    this.pathLength = this.path.getTotalLength();

    this.init();
  }

  init() {
    this.setOptions();
    gsap.set(this.path, {
      strokeDasharray: this.pathLength,
      strokeDashoffset: this.pathLength,
    });

    gsap.to(this.path, {
      strokeDashoffset: this.options.offset,
      ease: 'none',
      scrollTrigger: {
        trigger: this.element,
        start: 'top center',
        end: 'bottom center',
        scrub: 0.5,
      },
    });
  }

  setOptions() {
    if ('offset' in this.element.dataset) {
      this.options.offset = this.element.dataset.offset;
      console.log(this.options.offset);
    }
  }
}
