import { gsap } from 'gsap';

export default class Raindrop {
  constructor(element) {
    this.element = element;
    this.dropletQuantity = 60;
    this.init();
  }

  init() {
    const fallDistance = 1100;

    for (let i = 0; i < this.dropletQuantity; i++) {
      //Vitesse de chute
      const SpeedVariation = Math.random();
      const speed = 45 + SpeedVariation * 50;
      //Distance / par vitesse pour avoir la vitesse de descente
      const duration = fallDistance / speed;

      //Créer l'élément div.droplet et lui assigne une position random
      const pos = Math.random() * 100;
      const droplet = document.createElement('div');
      droplet.className = 'droplet';
      droplet.style.left = `${pos}%`;

      //Créer des width et height random pour chaque droplets
      const width = 3 + Math.random() * 2;
      const height = 15 + Math.random() * 30;
      droplet.style.width = `${width}px`;
      droplet.style.height = `${height}px`;
      droplet.style.opacity = 1 + Math.random() * 0.1;

      //Assigne les droplet à la page HTML
      this.element.appendChild(droplet);

      //Gére les paramètres des droplets individuels
      gsap.to(droplet, {
        y: fallDistance,
        duration: duration,
        delay: -Math.random() * duration,
        repeat: -1,
        ease: 'none',
      });
    }
    //Appelle la fonction qui génère des points
    this.addStaticDots();
  }

  //Fonction qui crée des points statics blanc dans la page
  addStaticDots() {
    for (let i = 0; i < this.dropletQuantity; i++) {
      const dot = document.createElement('div');
      dot.className = 'dot';

      //Ajoute les sizes et leurs positions de façon random
      const size = 1 + Math.random() * 2; // 1px à 3px
      dot.style.width = `${size}px`;
      dot.style.height = `${size}px`;
      dot.style.left = `${Math.random() * 100}%`;
      dot.style.top = `${Math.random() * 100}%`;
      dot.style.opacity = 0.2 + Math.random() * 0.5;

      //L'ajoute à la page HTML
      this.element.appendChild(dot);
    }
  }
}
